@aware([
    'listboxId' => null,
    'size' => null,
])

@php
    use App\Support\Bladex\Form\FormControlClassMap;

    $formControl = app(FormControlClassMap::class);

    $contentClasses = collect([
        'select__content',
        $formControl->selectListboxClasses($size),
    ])->implode(' ');

    $contentAttributes = $attributes
        ->class($contentClasses)
        ->merge([
            'role' => 'listbox',
            'tabindex' => '-1',
            'hidden' => true,
        ])
        ->merge(['data-select-content' => '']);

    if (filled($listboxId)) {
        $contentAttributes = $contentAttributes->merge(['id' => $listboxId]);
    }
@endphp

<div {{ $contentAttributes }}>
    {{ $slot }}
</div>

@props([
    'name' => null,
    'value' => null,
    'placeholder' => null,
    'size' => null,
    'invalid' => false,
    'disabled' => false,
    'selectId' => null,
    'listboxId' => null,
    'shortcut' => true,
])

@php
    $selectId = filled($selectId)
        ? $selectId
        : 'select-'.str_replace('.', '', uniqid('', true));
    $listboxId = filled($listboxId) ? $listboxId : $selectId.'-listbox';
@endphp

<div
    {{ $attributes->except('shortcut')->class([
        'select relative min-w-0',
        'w-full' => ! filled($attributes->get('class')),
    ]) }}
    data-select
    data-select-id="{{ $selectId }}"
>
    @if (filled($name))
        <input
            type="hidden"
            name="{{ $name }}"
            value="{{ $value }}"
            data-select-hidden-input
        />
    @else
        <input
            type="hidden"
            value="{{ $value }}"
            data-select-hidden-input
        />
    @endif

    @if ($shortcut)
        <x-ui::select.trigger>
            <x-ui::select.value :placeholder="$placeholder" />
        </x-ui::select.trigger>

        <x-ui::select.content>
            {{ $slot }}
        </x-ui::select.content>
    @else
        {{ $slot }}
    @endif
</div>

@props([
    'value' => null,
    'disabled' => false,
])

@aware([
    'size' => null,
])

@php
    use App\Support\Bladex\Form\FormControlClassMap;

    $formControl = app(FormControlClassMap::class);

    $itemClasses = collect([
        'select__item',
        $formControl->selectOptionClasses($size),
        'aria-selected:font-medium',
        '[&[aria-selected=true]_[data-select-item-check]]:opacity-100',
    ])->implode(' ');

    $itemAttributes = $attributes
        ->class($itemClasses)
        ->merge([
            'role' => 'option',
            'data-select-item' => true,
            'aria-selected' => 'false',
            'tabindex' => '-1',
        ]);

    if (filled($value)) {
        $itemAttributes = $itemAttributes->merge(['data-value' => $value]);
    }

    if ($disabled) {
        $itemAttributes = $itemAttributes
            ->merge([
                'data-disabled' => true,
                'aria-disabled' => 'true',
            ]);
    }
@endphp

<div {{ $itemAttributes }}>
    <span class="min-w-0 flex-1 truncate" data-select-item-label>{{ $slot }}</span>
    <svg
        class="pointer-events-none absolute right-2 top-1/2 size-4 -translate-y-1/2 text-zinc-900 opacity-0 dark:text-zinc-50"
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        stroke-width="2"
        stroke-linecap="round"
        stroke-linejoin="round"
        aria-hidden="true"
        data-select-item-check
    >
        <path d="M20 6 9 17l-5-5" />
    </svg>
</div>

@aware([
    'size' => null,
])

@php
    $labelClasses = collect([
        'select__label',
        'px-2 pb-0.5 pt-1 text-xs font-medium text-zinc-500 dark:text-zinc-400',
    ])->implode(' ');
@endphp

<div
    {{ $attributes->class($labelClasses)->merge([
        'role' => 'presentation',
        'data-select-label' => true,
    ]) }}
>
    {{ $slot }}
</div>

@aware([
    'size' => null,
    'invalid' => false,
    'disabled' => false,
    'selectId' => null,
    'listboxId' => null,
])

@php
    use App\Support\Bladex\Form\FormControlClassMap;
    use App\Support\Bladex\Interaction\InteractionStateAttributes;

    $formControl = app(FormControlClassMap::class);
    $interactionState = app(InteractionStateAttributes::class);

    $triggerAttributes = $interactionState->apply(
        $attributes
            ->class([
                'select__trigger',
                'group flex w-full min-w-0 items-center justify-between gap-2 text-left',
                $formControl->fieldSurfaceClasses($size, includeReadOnly: false, cursor: 'pointer'),
                $formControl->invalidFieldClasses(),
                'aria-expanded:border-zinc-300 aria-expanded:ring-2 aria-expanded:ring-zinc-950/10',
                'dark:aria-expanded:border-zinc-600 dark:aria-expanded:ring-zinc-300/20',
                $invalid ? 'border-red-500 focus-visible:ring-red-500/20 dark:border-red-500' : null,
            ])
            ->merge([
                'type' => 'button',
                'aria-haspopup' => 'listbox',
                'aria-expanded' => 'false',
            ]),
        ['nativeDisabled' => true],
    );

    if ($invalid) {
        $triggerAttributes = $triggerAttributes->merge(['aria-invalid' => 'true']);
    }

    if ($disabled) {
        $triggerAttributes = $triggerAttributes->merge(['disabled' => true]);
    }

    if (filled($selectId)) {
        $triggerAttributes = $triggerAttributes->merge(['id' => $selectId.'-trigger']);
    }

    if (filled($listboxId)) {
        $triggerAttributes = $triggerAttributes->merge(['aria-controls' => $listboxId]);
    }

    $chevronClasses = $size === 'sm' ? 'size-3.5 shrink-0 opacity-50' : 'size-4 shrink-0 opacity-50';
@endphp

<button {{ $triggerAttributes }} data-select-trigger>
    <span class="select__trigger-inner flex min-w-0 flex-1 items-center gap-2">
        {{ $slot }}
    </span>
    <svg
        class="{{ $chevronClasses }} text-zinc-500 transition-transform duration-200 group-aria-expanded:rotate-180 dark:text-zinc-400"
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        stroke-width="2"
        stroke-linecap="round"
        stroke-linejoin="round"
        aria-hidden="true"
        data-select-chevron
    >
        <path d="m6 9 6 6 6-6" />
    </svg>
</button>

@aware([
    'placeholder' => null,
    'size' => null,
])

